import{_ as i,a0 as l,w as p,s as g,ao as a,I as n,x as t,a1 as e,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse(`{"title":"在 Linux 中使用 avconv 工具錄製計算機桌面視頻和音頻 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中使用 avconv 工具錄製計算機桌面視頻和音頻 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中使用 avconv 工具錄製計算機桌面視頻和音頻 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中使用 avconv 工具錄製計算機桌面視頻和音頻 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141108 How to Record Your Desktop Video and Audio Using 'Avconv' Tool in Ubuntu","title":"在 Linux 中使用 avconv 工具錄製計算機桌面視頻和音頻","tag":"201411","desc":""},"relativePath":"201411/20141108 How to Record Your Desktop Video and Audio Using 'Avconv' Tool in Ubuntu.md","filePath":"[post].md"}`),u={name:"201411/20141108 How to Record Your Desktop Video and Audio Using 'Avconv' Tool in Ubuntu.md"};function d(v,o,m,c,w,b){const r=l("Link");return p(),g("div",null,[o[19]||(o[19]=a(`<h1 id="在-linux-中使用-avconv-工具錄製計算機桌面視頻和音頻" tabindex="-1">在 Linux 中使用&quot;avconv&quot;工具錄製計算機桌面視頻和音頻 <a class="header-anchor" href="#在-linux-中使用-avconv-工具錄製計算機桌面視頻和音頻" aria-label="Permalink to “在 Linux 中使用avconv工具錄製計算機桌面視頻和音頻”">​</a></h1><p><strong>Libav</strong>是一款跨平台的工具庫，能夠用來處理多媒體文件、流和協議。它最初是源自ffmpeg。Libav帶有一些工具，比如：</p><ul><li><strong>Avplay</strong>： 一款視頻音頻播放器。</li><li><strong>Avconv</strong>： 能夠記錄多個設備輸入源的一個多媒體轉換器和視頻音頻錄製器。</li><li><strong>Avprobe</strong>： 一個連接多媒體文件流並且返回關於這個文件流的統計信息的工具。</li><li><strong>Libavfilter</strong>： 一個Libav工具的過濾器(filtering)API。</li></ul><p>在這篇文章裏面，我們就要展示如何通過&#39;Avconv&#39;程序在<strong>Debian/Ubuntu/Linux Mint</strong>發行版上錄製Linux桌面視頻音頻。</p><h3 id="第一步-下載-avconv-工具" tabindex="-1">第一步：下載 Avconv 工具 <a class="header-anchor" href="#第一步-下載-avconv-工具" aria-label="Permalink to “第一步：下載 Avconv 工具”">​</a></h3><p><strong>1.</strong> <strong>avconv</strong>是 “<strong>libav-tools</strong>” 的一部分， 可以通過官方的基於debian的倉庫下載，比如Mint、Ubuntu。輸入下面命令即可：</p><pre><code>$ sudo apt-get update
$ sudo apt-get install libav-tools
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Install-avconv-tool.jpeg" alt="Install Avconv Tool"></p><p><em>下載Avconv工具</em></p><p><strong>注意</strong>： 如果從默認倉庫下載的話， ‘<strong>avconv</strong>’ 的版本可能比較老。 因此我們推薦你拉取最新的git官方版本。</p><pre><code>$ sudo apt-get install yasm
$ git clone git://git.libav.org/libav.git
$ cd libav
$ ./configure
$ make
$ sudo make install
</code></pre><p><strong>注意</strong>： 你應該運行 ‘<strong>./configure –help</strong>’ 來列出所有的可選配置選項並且安裝相應的解碼器和庫，你還需要做很多工作來解決依賴問題。</p><p>也要注意，如果你是從源代碼編譯的，就需要使用<strong>sudo avconv</strong>而不是<strong>avconv</strong>來運行這個工具。</p><h3 id="第二步-開始錄製桌面視頻" tabindex="-1">第二步：開始錄製桌面視頻 <a class="header-anchor" href="#第二步-開始錄製桌面視頻" aria-label="Permalink to “第二步：開始錄製桌面視頻”">​</a></h3><p><strong>2.</strong>一切就緒，現在可以通過運行下面的命令錄製你的視頻了：</p><pre><code>$ avconv -f x11grab -r 25 -s 1920x1080 -i :0.0 -vcodec libx264 -threads 4 $HOME/output.avi
</code></pre><p>簡單解釋一下這個命令:</p><ul><li><strong>avconv -f x11grab</strong> 默認從X服務捕捉畫面。</li><li><strong>-r 25</strong> 這是你需要的視頻幀率，可以自行設置。</li><li><strong>-s 1920×1080</strong> 是你的系統的桌面分辨率，要設置成你當前桌面的分辨率，這一點非常重要。</li><li><strong>-i :0.0</strong> 我們要記錄的位置（X 服務輸出端口），設置成這樣就可以了。</li><li><strong>-vcodec libx264</strong> 我們用來錄製視頻的編碼器。</li><li><strong>-threads 4</strong> 線程數，可以根據情況更改。</li><li><strong>$HOME/output</strong> 輸出的目標文件路徑。</li><li><strong>.avi</strong> 使用的視頻格式，可以換成 “flv”、“mp4″、 “wmv”、 “mov”、 “mkv”等。</li></ul><p><strong>3.</strong>在運行命令之後，就會在terminal上自動運行一個進程進行記錄，按&quot;Ctrl+C&quot;鍵來終止記錄。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Record-Desktop-Screen.jpeg" alt="Record Desktop Screen"></p><p><em>錄製桌面視頻</em></p><p><strong>4.</strong> 現在，你可以使用VLC或者其他的播放器，或者使用來自Libav包裏的播放器&quot;avplay&quot;來播放你錄製的視頻。</p><pre><code>$ avplay $HOME/output.avi
</code></pre><p><strong>注意:</strong> 別忘了替換輸出文件的路徑為你自己的，錄製效果還是很好的。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Play-Recorded-Video.jpeg" alt="Play Recorded Video"></p><p><em>播放錄製的文件</em></p>`,26)),n("p",null,[o[1]||(o[1]=t("這有一段我用 “",-1)),o[2]||(o[2]=n("strong",null,"avconv",-1)),o[3]||(o[3]=t("” 錄製的",-1)),e(r,{href:"http://www.youtube.com/embed/g1FEh4wByGE"},{default:s(()=>[...o[0]||(o[0]=[t("視頻",-1)])]),_:1}),o[4]||(o[4]=t(" （牆外）。",-1))]),o[20]||(o[20]=a(`<h3 id="第三步-開始錄製桌面的音頻和視頻" tabindex="-1">第三步： 開始錄製桌面的音頻和視頻 <a class="header-anchor" href="#第三步-開始錄製桌面的音頻和視頻" aria-label="Permalink to “第三步： 開始錄製桌面的音頻和視頻”">​</a></h3><p><strong>5.</strong> 如果也想同時錄製音頻，先運行這個命令，列出所有的音頻輸入源：</p><pre><code>$ arecord -l
</code></pre><p>結果類似這樣：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Audio-Input.png" alt="Check Audio Input"></p><p><em>檢查音頻輸入源</em></p><p>在我這裏，我只有一個音頻輸入源，所以數量是<strong>1</strong>，這就是我使用如下命令來捕捉我的視頻以及麥克風的音頻的原因。</p><pre><code>$ avconv -f alsa -i hw:1 -f x11grab -r 25 -s 1920x1080 -i :0.0 -vcodec libx264 -threads 4 output-file2.avi
</code></pre><p>我修改了部分地方，下面做個簡短的解釋：</p><ul><li><strong>-f</strong> alsa 一個從alsa設備捕捉聲音的選項。</li><li><strong>-i</strong> hw:1 是一個從 “hw:1” 設備捕捉音頻的選項，這個設備是我電腦上僅有的一個音頻輸入設備。</li></ul><p><strong>注意</strong>: 如果你想用<strong>arecord -l</strong>顯示的<strong>1</strong>之外的設備的話，別忘了替換 “<strong>1</strong>”。</p><p>結束錄製，再來一次“<strong>Ctrl + C</strong>” 就可以。</p><h3 id="第四步-開始錄製桌面音頻" tabindex="-1">第四步： 開始錄製桌面音頻 <a class="header-anchor" href="#第四步-開始錄製桌面音頻" aria-label="Permalink to “第四步： 開始錄製桌面音頻”">​</a></h3><p><strong>6.</strong> 如果只想錄製音頻的話，使用下面的命令。</p><pre><code>$ avconv -f alsa -i hw:1 out.wav
</code></pre><p><strong>7.</strong> 替換成 <strong>.mp3</strong> 等Libav支持的格式都可以，播放 <strong>out.wav</strong>就能聽到你自己的聲音了。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Record-Desktop-Audio.png" alt="Record Desktop Audio"></p><p><em>錄製桌面音頻</em></p><p>###最後 ###</p><p>“<strong>avconv</strong>” 工具可以用來做很多其他事情，不僅僅是錄製桌面視頻，更多的教程和文檔請移步到官網。</p>`,20)),n("ul",null,[n("li",null,[e(r,{href:"https://libav.org/avconv.html"},{default:s(()=>[...o[5]||(o[5]=[t("https://libav.org/avconv.html",-1)])]),_:1})])]),o[21]||(o[21]=n("p",null,'你對"avconv"的體驗如何，你使用過其他工具錄製桌面視頻麼？在評論裏面和我們分享吧。',-1)),o[22]||(o[22]=n("hr",null,null,-1)),n("p",null,[o[7]||(o[7]=t("via: ",-1)),e(r,{href:"http://www.tecmint.com/record-ubuntu-desktop-screen-using-avconv/"},{default:s(()=>[...o[6]||(o[6]=[t("http://www.tecmint.com/record-ubuntu-desktop-screen-using-avconv/",-1)])]),_:1})]),n("p",null,[o[11]||(o[11]=t("作者：",-1)),e(r,{href:"http://www.tecmint.com/author/hannyhelal/"},{default:s(()=>[...o[8]||(o[8]=[t("Hanny Helal",-1)])]),_:1}),o[12]||(o[12]=t(" 譯者：",-1)),e(r,{href:"https://github.com/ggaaooppeenngg"},{default:s(()=>[...o[9]||(o[9]=[t("ggaaooppeenngg",-1)])]),_:1}),o[13]||(o[13]=t(" 校對：",-1)),e(r,{href:"https://github.com/wxy"},{default:s(()=>[...o[10]||(o[10]=[t("wxy",-1)])]),_:1})]),n("p",null,[o[16]||(o[16]=t("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...o[14]||(o[14]=[t("LCTT",-1)])]),_:1}),o[17]||(o[17]=t(" 原創翻譯，",-1)),e(r,{href:"http://linux.cn/"},{default:s(()=>[...o[15]||(o[15]=[t("Linux中國",-1)])]),_:1}),o[18]||(o[18]=t(" 榮譽推出",-1))])])}const h=i(u,[["render",d]]);export{T as __pageData,h as default};
